<script setup lang="ts">
import { ArrowLeft, ArrowUpRight, BusFront, MapPin, Clock3, UserRound, CalendarDays } from 'lucide-vue-next'
import { apiErrorMessage } from '~/utils/api-errors'
import { displayDate, displayTime, displayPrice, displayDuration, tripStatusLabels } from '~/utils/display'
const route = useRoute()
const api = useTransportApi()
const id = computed(() => Number(route.params.id))
const { data: trip, pending, error, refresh } = await useAsyncData(() => `public-trip-${id.value}`, () => api.trips.get(id.value))
useHead({ title: computed(() => trip.value ? `Рейс № ${trip.value.id}` : 'Рейс') })
const sortedStops = computed(() => [...(trip.value?.stops || [])].sort((a,b) => a.stop_order - b.stop_order))
const errorMessage = computed(() => error.value ? apiErrorMessage(error.value) : null)
</script>
<template><div class="container-page"><NuxtLink to="/trips" class="back-link"><ArrowLeft :size="15"/>Все рейсы</NuxtLink><TransportDataState :pending="pending" :error="errorMessage" @retry="refresh"/><template v-if="trip && !pending && !error"><div class="page-heading"><div><p class="page-eyebrow">ДЕТАЛИ ПОЕЗДКИ</p><h1 class="page-title">{{ sortedStops[0]?.stop.name || 'Рейс' }} <span class="text-muted">→</span> {{ sortedStops[sortedStops.length-1]?.stop.name || `№ ${trip.id}` }}</h1><p class="page-description">Рейс № {{ trip.id }} · {{ displayDate(trip.start_time) }} · {{ displayDuration(trip.start_time,trip.end_time) }}</p></div><span class="badge badge-blue">{{ tripStatusLabels[trip.status] || trip.status }}</span></div><div class="detail-grid"><section class="panel card-pad"><div class="section-head"><h2 class="section-label">Маршрут и остановки</h2><span class="badge">{{ sortedStops.length }} остановок</span></div><p class="schedule-note">Время отображается в часовом поясе вашего устройства.</p><ol v-if="sortedStops.length" class="timeline"><li v-for="(item,index) in sortedStops" :key="item.id"><div class="timeline-time"><strong>{{ displayTime(index === 0 ? item.departure_time : item.arrival_time) }}</strong><span>{{ displayDate(index === 0 ? item.departure_time : item.arrival_time) }}</span></div><div class="timeline-marker"><span></span></div><div class="timeline-stop"><NuxtLink :to="`/stops/${item.stop.id}`">{{ item.stop.name }} <ArrowUpRight :size="12"/></NuxtLink><p>{{ item.stop.address }}</p><div class="stop-timing"><span>Прибытие {{ displayTime(item.arrival_time) }}</span><span>Отправление {{ displayTime(item.departure_time) }}</span></div><p v-if="index < sortedStops.length - 1" class="segment-price">До следующей остановки: {{ displayPrice(item.price_to_next) }} ₽</p></div></li></ol><TransportDataState v-else empty title="Остановки ещё не добавлены" description="Подробности маршрута появятся после публикации расписания."/></section><aside class="details-sidebar"><section class="panel card-pad"><p class="text-muted price-label">Базовая стоимость рейса</p><p class="detail-price">{{ displayPrice(trip.base_price) }} <span>₽</span></p><div class="price-divider"></div><p class="booking-note">Онлайн-бронирование пока недоступно. Вы можете ознакомиться с расписанием и транспортом.</p><NuxtLink to="/trips" class="btn btn-secondary all-trips">Другие рейсы <ArrowUpRight :size="14"/></NuxtLink></section><section class="panel card-pad"><h2 class="section-label">Транспорт и водитель</h2><NuxtLink :to="`/buses/${trip.bus.id}`" class="related-resource"><span class="related-icon"><BusFront :size="20"/></span><div><strong>{{ trip.bus.brand }}</strong><span>{{ trip.bus.license_plate }} · {{ trip.bus.capacity }} мест</span></div><ArrowUpRight :size="15"/></NuxtLink><NuxtLink :to="`/drivers/${trip.driver.id}`" class="related-resource"><span class="related-icon"><UserRound :size="20"/></span><div><strong>{{ trip.driver.last_name }} {{ trip.driver.first_name }}</strong><span>{{ trip.driver.middle_name || 'Водитель рейса' }}</span></div><ArrowUpRight :size="15"/></NuxtLink></section><section class="panel card-pad"><h2 class="section-label">Расписание рейса</h2><dl class="schedule-data"><dt>Отправление</dt><dd>{{ displayDate(trip.start_time) }}, {{ displayTime(trip.start_time) }}</dd><dt>Прибытие</dt><dd>{{ trip.end_time ? `${displayDate(trip.end_time)}, ${displayTime(trip.end_time)}` : 'Не указано' }}</dd></dl></section></aside></div></template></div></template>
